#!/usr/bin/env python3
# Coverage: filtered nth-child/nth-last-child, unions, non-elements, :has/:scope, live mutation,
# legacy nth-child, ordering/deduplication, and malformed filters. Each assertion names a wrong
# implementation it rejects (counting all siblings, taking only the first match, caching results,
# or accepting a malformed branch).
import os, sys, tempfile, subprocess
root = os.path.abspath(os.path.join(os.path.dirname(__file__), '..'))
java = r'''
import org.jsoup.Jsoup;
import org.jsoup.nodes.*;
import org.jsoup.select.*;
import java.util.*;
public class NthOfAcceptance {
  static void ids(String label, Elements es, String... want) {
    List<String> got = new ArrayList<>();
    for (Element e : es) got.add(e.id());
    System.out.println(label + " -> " + got);
    if (!got.equals(Arrays.asList(want))) throw new AssertionError(label+" expected "+Arrays.asList(want)+" got "+got);
  }
  static void parseFails(String q) {
    try {
      Jsoup.parse("<ul><li></li></ul>").select(q);
      throw new AssertionError("accepted invalid selector: "+q);
    } catch (Selector.SelectorParseException expected) {
      System.out.println("rejected -> " + q);
    }
  }
  public static void main(String[] args) {
    Document d = Jsoup.parse("<ul id=u><!--x--><li id=a class=ready data-kind=card></li>text<li id=b data-kind=ad></li><li id=c data-kind=card></li><li id=d disabled data-kind=card></li><li id=e class=ready></li></ul>");
    ids("filtered odd union", d.select("li:nth-child(2n+1 of .ready, [data-kind=card])"), "a", "d");
    ids("filtered odd excluding disabled", d.select("li:nth-child(2n+1 of .ready, [data-kind=card]:not([disabled]))"), "a", "e");
    ids("reverse last", d.select("li:nth-last-child(1 of .ready, [data-kind=card])"), "e");
    ids("reverse second", d.select("li:nth-last-child(2 of .ready, [data-kind=card])"), "d");
    ids("plain nth unchanged", d.select("li:nth-child(2)"), "b");
    ids("comma dedupe/order", d.select("li:nth-child(1 of .ready), li:nth-child(1 of [data-kind=card])"), "a");

    Document m = Jsoup.parse("<ul><li id=a class=k></li><li id=b class=k></li><li id=c class=k></li><li id=d class=k></li></ul>");
    Evaluator ev = Selector.evaluatorOf("li:nth-child(odd of .k)");
    ids("initial", m.select(ev), "a", "c");
    m.expectFirst("#a").remove(); ids("after remove", m.select(ev), "b", "d");
    m.expectFirst("ul").appendChild(m.expectFirst("#b")); ids("after move", m.select(ev), "c", "b");
    m.expectFirst("#c").removeClass("k"); ids("after filter mutation", m.select(ev), "d");
    m.expectFirst("#c").addClass("k"); ids("repeat stable", m.select(ev), "d", "c");

    Document s = Jsoup.parse("<section id=scope><span id=x class=z></span><div id=a class=z></div><div id=b class=z></div><div id=c></div></section>");
    ids("mixed element candidates", s.select("div:nth-child(odd of .z)"), "b");
    ids("nested has filter", s.select("div:nth-child(1 of :has(+ div.z))"), "a");
    ids("scope filter", s.expectFirst("#scope").select("div:nth-child(1 of :scope > div.z)"), "a");

    parseFails("li:nth-child(of .x)");
    parseFails("li:nth-child(2n+1 of )");
    parseFails("li:nth-child(2n+1 of .x");
    parseFails("li:nth-child(2x+1 of .x)");
    parseFails("li:nth-child(2n+1 of :bogus)");
    parseFails("li:nth-child(2n+1 of .x >)");
    System.out.println("nth-of acceptance passed");
  }
}
'''
