/**
 Get the data that this form submits. The returned list is a copy of the data, and changes to the contents of the
 list will not be reflected in the DOM.
 <p>Only successful controls are included, matching browser form submission rules: controls without a
 {@code name}, disabled controls, and controls disabled through a {@code <fieldset disabled>} ancestor are skipped
 (controls in the fieldset's first {@code <legend>} subtree are exempt). For {@code <select>}, disabled options and
 options in a disabled {@code <optgroup>} are skipped; a non-multiple select with no selected option contributes its
 first available option. Checkboxes and radios are only included when checked, defaulting to the value
 {@code on}; {@code <input type=button>} and {@code type=image>} are never included.</p>
 <p>As no submitter is given, submit buttons ({@code <input type=submit>}, {@code <button>}, and
 {@code <input type=image>}) are not treated as ordinary fields and contribute nothing. Pass the activated button
 to {@link #formData(Element)} to include it as the submitter.</p>
 @return a list of key vals, in the order the controls appear in the document; empty if none apply
 @see #formData(Element)
 */
public List<Connection.KeyVal> formData() {
    return formData(null);
}

/**
 Get the data that this form submits when activated through {@code submitter}. Equivalent to {@link #formData()},
 except that the submitter is appended (in document-order position of the surrounding controls it naturally comes
 last among them) when it is a named, enabled submit button associated with this form, and other submit buttons are
 still excluded.
 <p>The submitter may be an {@code <input type=submit>} or {@code type=image>} (an image control contributes its
 coordinates, here {@code name.x=0} and {@code name.y=0}, or plain {@code x}/{@code y} when unnamed, per the
 browser convention), or a {@code <button type=submit>} (the default {@code type}). A {@code type=button},
 {@code type=reset}, or other non-submitting control is rejected.</p>
 @param submitter the button used to submit the form, or {@code null} to collect without a submitter
 @return a list of key vals, in the order the controls appear in the document; empty if none apply
 @throws IllegalArgumentException if the submitter is not a submit button associated with this form, is unnamed in
 a context that requires a name, or is disabled
 */
public List<Connection.KeyVal> formData(@Nullable Element submitter) {
    ArrayList<Connection.KeyVal> data = new ArrayList<>();

    // iterate the associated form controls and accumulate their values
    for (Element el : elements()) {
        if (!el.tag().isFormSubmittable()) continue; // listed elements are a superset of submittable ones
        if (el.hasAttr("disabled")) continue; // skip disabled form inputs
        String name = el.attr("name");
        if (name.length() == 0) continue;
        String type = el.attr("type");

        if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
        if (isSubmitButton(el, type)) {
            // submit buttons are only successful when they are the explicit submitter
            if (submitter != null && el == submitter)
                addSubmitterData(el, name, type, data);
            continue;
        }

        if (isInDisabledFieldset(el)) continue; // first legend subtree of a disabled fieldset is exempt

        if (el.nameIs("select")) {
            addSelectData(el, name, data);
        } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
            // only add checkbox or radio if they have the checked attribute
            if (el.hasAttr("checked")) {
                final String val = el.hasAttr("value") ? el.attr("value") : "on";
                data.add(HttpConnection.KeyVal.create(name, val));
            }
        } else {
            // textarea#val() returns its text; other controls use their value attribute
            data.add(HttpConnection.KeyVal.create(name, el.val()));
        }
    }

    if (submitter != null) {
        Validate.notNullParam(submitter, "submitter");
        if (!isSubmitButton(submitter, submitter.attr("type")) || submitter.hasAttr("disabled")
            || submitter.attr("name").length() == 0 || !elements().contains(submitter)) {
            throw new IllegalArgumentException(
                "Submitter must be a named, enabled submit button associated with this form.");
        }
        if (!data.stream().anyMatch(kv -> kv.key().startsWith(submitter.attr("name"))))
            addSubmitterData(submitter, submitter.attr("name"), submitter.attr("type"), data);
    }
    return data;
}

/** A control that is only successful when it activates the form: submit/reset inputs and {@code <button>}. */
private static boolean isSubmitButton(Element el, String type) {
    if (el.nameIs("button"))
        return !"button".equalsIgnoreCase(type) && !"reset".equalsIgnoreCase(type); // default type is submit
    return el.nameIs("input") && "submit".equalsIgnoreCase(type);
}

/** Append the successful value(s) of an activated submit button. */
private static void addSubmitterData(Element el, String name, String type, ArrayList<Connection.KeyVal> data) {
    if ("image".equalsIgnoreCase(type)) {
        // an image submitter sends x/y click coordinates
        data.add(HttpConnection.KeyVal.create(name + ".x", "0"));
        data.add(HttpConnection.KeyVal.create(name + ".y", "0"));
    } else {
        data.add(HttpConnection.KeyVal.create(name, el.val()));
    }
}

