    System.out.println(sb + "]");
  }
  public static void main(String[] a) {
    // malformed / partial
    show("empty", Jsoup.parse("<form></form>").expectForm("form").formData());
    show("partial", Jsoup.parse("<form><input name='a' value='1'<select name='s'><option><option selected>x").expectForm("form").formData());
    show("dup options", Jsoup.parse("<form><select name=s><option selected>1<option selected>2</select>").expectForm("form").formData());
    // submitter in first legend of disabled fieldset is enabled
    Document d = Jsoup.parse("<form><fieldset disabled><legend><input id=go type=submit name=go value=G></legend>" +
        "<input name=x value=1></fieldset></form>");
    FormElement f = d.expectForm("form");
    show("legend submitter", f.formData(d.getElementById("go")));
    // submitter in disabled fieldset body rejected
    Document d2 = Jsoup.parse("<form><fieldset disabled><input id=go2 type=submit name=go2 value=G2></fieldset></form>");
    try { d2.expectForm("form").formData(d2.getElementById("go2")); System.out.println("ERROR: no exception"); }
    catch (IllegalArgumentException e) { System.out.println("disabled fieldset submitter rejected: " + e.getMessage()); }
    // null submitter equals no-arg
    System.out.println("null == noarg: " + f.formData(null).equals(f.formData()));
    // type=submit with empty value attr
    show("empty value submit", Jsoup.parse("<form><input name=a value=1><input id=s type=submit name=go></form>")
        .expectForm("form").formData(Jsoup.parse("<x>").getElementById("x") == null ? null : null));
    Document d3 = Jsoup.parse("<form><input name=a value=1><input id=s type=submit name=go></form>");
    show("empty value submit", d3.expectForm("form").formData(d3.getElementById("s")));
    // button type=submit explicit
    Document d4 = Jsoup.parse("<form><button id=b type=submit name=ok value=yes>Hi</button></form>");
    show("button submit", d4.expectForm("form").formData(d4.getElementById("b")));
  }
}
